declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Auth.php';require_once __DIR__.'/../app/SkillCatalog.php';try{$u=(new Auth($config))->requireUser();$sc=new SkillCatalog($config);if($_SERVER['REQUEST_METHOD']==='GET')json_response(['ok'=>true,'items'=>$sc->list()]);if(($u['role']??'guest')!=='admin')json_response(['ok'=>false,'error'=>'Somente administradores podem alterar habilidades.'],403);$action=(string)($_POST['action']??$_GET['action']??'');if($action==='upload_zip'){if(!isset($_FILES['skill_zip'])||!is_array($_FILES['skill_zip']))throw new InvalidArgumentException('Selecione um arquivo ZIP.');$f=$_FILES['skill_zip'];if((int)($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('Falha no upload do ZIP.');if((string)($f['type']??'')!==''&&!in_array((string)$f['type'],['application/zip','application/x-zip-compressed','application/octet-stream'],true))throw new InvalidArgumentException('O arquivo precisa ser ZIP.');json_response(['ok'=>true,'skill'=>$sc->importZip((string)$f['tmp_name'])]);}$in=request_json();$action=(string)($in['action']??'install');if($action==='seed')json_response(['ok'=>true,'installed'=>$sc->seed(),'items'=>$sc->list()]);if($action==='enable')json_response(['ok'=>true,'skill'=>$sc->setEnabled((string)($in['name']??''),true)]);if($action==='disable')json_response(['ok'=>true,'skill'=>$sc->setEnabled((string)($in['name']??''),false)]);if($action==='install')json_response(['ok'=>true,'skill'=>$sc->install($in)]);throw new InvalidArgumentException('Ação de habilidade inválida.');}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
